import {esc,num,table,notes,sources,controlsHTML as baseControls,readControls,resultHTML as baseResult,bindResult as bindBase} from './bridges-views.js?v=20261030-construction1';
export {esc,num,table,notes,sources,readControls};
export function controlsHTML(module,values){const keys=module.id==='order'?['etaX','etaY','etaZ','basisAngle']:module.id==='exchange'?['dz','conventionAngle']:['fieldZ','gammaPhi','basisAngle'];return baseControls({...module,fields:module.fields.map(f=>f.type==='number'&&f.key!=='points'?{...f,step:'any'}:f)},values)+`<details class="pr-sliders"><summary>拖动参数进行对照</summary><p>拖动同步更新上方输入；点击计算后更新结果。</p>${module.fields.filter(f=>keys.includes(f.key)).map(f=>`<label>${esc(f.label)}<input type="range" data-pr-control="${esc(f.key)}" min="${f.min??-5}" max="${f.max??5}" step="${f.step??.1}" value="${esc(values[f.key])}"></label>`).join('')}</details>`;}
const value=x=>typeof x==='number'?num(x):x===null||x===undefined?'—':typeof x==='object'?JSON.stringify(x):String(x);
const label=k=>({generator:'生成元',operation:'操作',formula:'约束方程',relations:'系数关系',inputResidual:'投影前残差',outputResidual:'投影后残差',degree:'多项式次数',relation:'约束关系',matrix:'矩阵',rotation:'坐标变换矩阵',vector:'序参量坐标',tensor:'交换张量',D:'D 向量',levels:'能级',energyResidual:'能谱差异',residual:'不变性残差',retained:'保留此序参量',fieldRetained:'保留外场',label:'名称',id:'标识',energy:'能量',selected:'当前诊断'})[k]||k;
const moreLabels={polarMatrix:'极向量变换矩阵',axialMatrix:'轴向量变换矩阵',swapsSites:'是否交换两个端点',hamiltonianNorm:'Hamiltonian 对易子范数',totalAdjointNorm:'完整伴随生成元作用范数',dissipatorNorm:'耗散贡献范数',hamiltonianConserved:'闭系统对所有初态守恒',conserved:'完整动力学对所有初态守恒',commutator:'对易子矩阵',totalAdjoint:'完整伴随作用矩阵',contributions:'Hamiltonian 各项的贡献',channels:'各耗散通道的贡献',term:'作用项',coefficient:'系数',norm:'矩阵范数',channel:'耗散通道',re:'实部',im:'虚部',timeReversalSquare:'时间反演平方',timeReversalResidual:'时间反演残差',timeReversalSymmetric:'是否保留时间反演',kramersProtected:'是否有 Kramers 保护',squareResidual:'反幺正平方残差',multiplicity:'数值简并度',explanation:'解释',interpretation:'物理解释',angleDegrees:'角度（度）',axis:'旋转轴',definition:'约定定义',swapSites:'交换端点标记',original:'原约定',transformed:'新约定',energyResidual:'能谱差异',expectationResidual:'期望值差异',stateResidual:'态演化协变残差',adjointResidual:'伴随作用协变残差',spin1:'第一个经典自旋方向',spin2:'第二个经典自旋方向',singularValues:'交换张量奇异值',convention:'使用约定',statement:'结论',hamiltonian:'Hamiltonian',observable:'观测算符',initialState:'初态',unitary:'换基矩阵',D:'D 向量'};
Object.assign(moreLabels,{sourcePowers:'原单项式各分量次数',targetPowers:'变换后单项式各分量次数',sign:'变换符号',rule:'变换规则',field:'外场坐标',operations:'变换后的群操作',covarianceResidual:'协变残差',description:'说明',operator:'生成元矩阵',adjoint:'完整伴随作用矩阵',trivial:'是否为平凡常数算符',factor:'矩阵元',globalSU2:'Hamiltonian 是否具有全局 SU(2) 对称性',reason:'判断依据',scope:'适用范围',eigenvalues:'全部本征值',timeReversalUnitary:'时间反演的幺正部分',originalHamiltonian:'原 Hamiltonian',transformedHamiltonian:'换基后的 Hamiltonian',originalObservable:'原观测算符',transformedObservable:'换基后的观测算符',maximumMultiplicity:'最大奇异值的重数',angleDegrees:'夹角（度）'});
const title=k=>moreLabels[k]||label(k);
function detail(x,depth=0){if(Array.isArray(x)&&x.length&&x.every(r=>Array.isArray(r)&&r.every(v=>typeof v!=='object')))return table(x[0].map((_,i)=>'列 '+i),x.map(r=>r.map(value)));if(x&&typeof x==='object'){const entries=Object.entries(x),simple=entries.filter(([,v])=>!v||typeof v!=='object'),nested=entries.filter(([,v])=>v&&typeof v==='object');return (simple.length?table(['项目','结果'],simple.map(([k,v])=>[title(k),typeof v==='boolean'?(v?'是':'否'):value(v)])):'')+nested.map(([k,v])=>`<details${depth===0?' open':''}><summary>${esc(Array.isArray(x)?'第 '+(Number(k)+1)+' 项':title(k))}</summary>${depth<4?detail(v,depth+1):`<pre>${esc(JSON.stringify(v,null,2))}</pre>`}</details>`).join('');}return `<p>${esc(value(x))}</p>`;}
function vectorSVG(vectors){const project=([x=0,y=0,z=0])=>[300+100*x-45*y,170-100*z+40*y];const max=Math.max(1,...vectors.flatMap(v=>v.vector||[]).map(Math.abs));return `<svg viewBox="0 0 600 350" role="img" aria-label="模型坐标下的向量；投影长度仅为示意"><defs><marker id="pr-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3z" fill="#277a64"/></marker></defs>${[[1.6,0,0,'x'],[0,1.6,0,'y'],[0,0,1.4,'z']].map(p=>{const e=project(p);return `<path d="M300 170L${e[0]} ${e[1]}" stroke="#a0b2a6"/><text x="${e[0]}" y="${e[1]-8}">${p[3]}</text>`;}).join('')}${vectors.map((v,i)=>{const q=project(v.vector.map(x=>x/max));return `<path d="M300 170L${q[0]} ${q[1]}" stroke="${i?'#b27c31':'#277a64'}" stroke-width="4" marker-end="url(#pr-arrow)"/><text x="${q[0]+10}" y="${q[1]+i*20}">${esc(v.label)}</text>`;}).join('')}</svg>`;}
function proofRows(module,r){return module==='order'?r.order?.constraintSources||[]:module==='exchange'?r.exchange?.constraints||[]:r.conservation?.proofs||[];}
export function resultHTML(module,r){const rows=proofRows(module,r),ops=r.order?.operations||[];return `<section class="pr-evidence"><h3>约束来源推导</h3><p>选择一条约束，检查实际变换、系数关系或生成元作用；对称性允许的项仍可因参数取值而为零。</p><label>查看推导<select id="pr-proof">${rows.map((x,i)=>`<option value="${i}">${esc(x.label||x.generator||x.operation||x.name||x.id||'约束 '+(i+1))}</option>`).join('')}</select></label><div id="pr-proof-info"></div></section>${module==='order'?`<section class="pr-evidence"><h3>序参量与保留操作</h3><label>作用的群元素<select id="pr-operation">${ops.map((x,i)=>`<option value="${i}">${esc(x.label||x.id)} · ${x.retained?'保留':'改变'}方向</option>`).join('')}</select></label><div id="pr-operation-info"></div><div id="pr-vector"></div><p>箭头显示序参量表示空间，不自动等同于真实晶体的原子位移。</p></section>`:''}${module==='exchange'?'<section class="pr-evidence"><h3>交换张量与自旋方向</h3><div id="pr-spin"></div><div id="pr-spin-info"></div></section>':''}<section class="pr-evidence"><h3>约定对照：一致变换后再比较</h3><p>结果来自当前输入的坐标或基底变换，同时变换算符和状态。修改上方约定参数后重新计算。</p><div id="pr-convention"></div></section>${module==='conservation'?'<section class="pr-evidence"><h3>简并保护诊断</h3><p>先检查反幺正对称性与平方，再判断能级简并是否受到本模型时间反演保护。</p><div id="pr-degeneracy"></div></section>':''}${baseResult('',r)}`;}
export function bindResult(module,r,root){bindBase('',r,root);const $=s=>root.querySelector(s),rows=proofRows(module,r),draw=()=>{$('#pr-proof-info').innerHTML=detail(rows[Number($('#pr-proof').value)]||'当前没有独立约束。');};$('#pr-proof').onchange=draw;draw();$('#pr-convention').innerHTML=detail(r.order?.convention||r.convention||r.conservation?.convention);
 if(module==='order'){const drawOp=()=>{const o=r.order.operations[Number($('#pr-operation').value)],v=r.order.vector,t=o.matrix.map(row=>row.reduce((s,x,i)=>s+x*v[i],0));$('#pr-operation-info').innerHTML=detail({operation:o.label||o.id,vector:t,retained:o.retained,fieldRetained:o.fieldRetained});$('#pr-vector').innerHTML=vectorSVG([{label:'η',vector:v},{label:'D(g)η',vector:t}]);};$('#pr-operation').onchange=drawOp;drawOp();}
 if(module==='exchange'){$('#pr-spin').innerHTML=vectorSVG([{label:'D',vector:r.exchange.D},{label:'S₁',vector:r.classical.spin1},{label:'S₂',vector:r.classical.spin2}]);$('#pr-spin-info').innerHTML=detail(r.classical);}
 if(module==='conservation')$('#pr-degeneracy').innerHTML=detail(r.conservation.degeneracy);
}
